def gpx_fields_to_xml(instance: Any, tag: str, version: str, custom_attributes: Dict[str, str]={}, nsmap: Dict[str, str]={}, prettyprint: bool=True, indent: str='', empty_body: bool=False) ->str:
    fields = instance.gpx_10_fields
    if version == '1.1':
        fields = instance.gpx_11_fields

    if not prettyprint:
        indent = ''

    attributes = []
    body = []

    node_path = ['']

    for gpx_field in fields:
        if isinstance(gpx_field, str):
            sentinel, fieldname = _check_dependents(instance, gpx_field)
            if sentinel:
                node_path.append(sentinel)
            else:
                if fieldname.startswith('/'):
                    node_path.pop()
                else:
                    node_path.append(fieldname)
        else:
            if len(node_path) > 0 and isinstance(node_path[-1], str) and node_path[-1].startswith('/'):
                continue
            value = getattr(instance, gpx_field.name)
            if gpx_field.attribute:
                xml_value = gpx_field.to_xml(value, version, nsmap, prettyprint=prettyprint, indent=indent)
                if xml_value:
                    attributes.append(xml_value)
            else:
                xml_value = gpx_field.to_xml(value, version, nsmap, prettyprint=prettyprint, indent=f'{indent}  ')
                if xml_value:
                    body.append(xml_value)

    for attr_name, attr_value in custom_attributes.items():
        attributes.append(f'{attr_name}="{attr_value}"')

    if tag is None:
        return ''.join(body)

    attr_str = ' '.join(attributes)
    if attr_str:
        attr_str = ' ' + attr_str

    body_str = ''.join(body)

    if not body_str and not empty_body:
        return ''

    if not body_str:
        return f'\n{indent}<{tag}{attr_str} />'

    return f'\n{indent}<{tag}{attr_str}>{body_str}\n{indent}</{tag}>'
